import { useState, useRef } from "react";

//-----------------------------------------------------
// Rendering 
//-----------------------------------------------------
function GameConstructor() {
  const [gameType, setGameType] = useState('wheel');
  const [gameContent, setGameContent] = useState(null);
  const [gameName, setGameName] = useState('My Test Wheel Game');

  const handleGameNaming = (event) => {
    setGameName(event.target.value);
  };

  const handleContent = () => {
    setGameContent();
  };

  function ConstructorEngine(gameType, gameContent, gameName) {
    if (gameType === 'wheel') {
      return <WheelGame gameName={gameName} />;
    } else if (gameType === 'match') {
      return (
        <div className="mt-8 p-6 bg-white rounded-xl shadow-lg">
          <h3 className="text-xl font-bold text-gray-800 mb-4">Match Game: {gameName || 'Untitled Game'}</h3>
          <p className="text-gray-600">Matching game functionality coming soon!</p>
        </div>
      );
    } else if (gameType === 'quiz') {
      return (
        <div className="mt-8 p-6 bg-white rounded-xl shadow-lg">
          <h3 className="text-xl font-bold text-gray-800 mb-4">Quiz Game: {gameName || 'Untitled Game'}</h3>
          <p className="text-gray-600">Quiz game functionality coming soon!</p>
        </div>
      );
    }
    return null;
  }
        
//-----------------------------------------------------
// Render Games
//-----------------------------------------------------
  return (
    <div className="min-h-screen p-4" style={{background: 'var(--background-blue)'}}>
      <div className="max-w-4xl mx-auto">
        <div className="text-center mb-8">
          <h1 className="text-4xl font-bold" style={{color: 'var(--text-dark)'}}>Game Constructor</h1>
          <p style={{color: 'var(--text-light)'}}>Create and customize your interactive games</p>
        </div>
        
        <div className="bg-white rounded-xl shadow-lg p-6 mb-8">
          <form onSubmit={(e) => e.preventDefault()} className="mb-6">
            <label className="block text-sm font-medium mb-2" style={{color: 'var(--text-dark)'}}>
              Enter game name
              <input
                type="text"
                value={gameName}
                onChange={handleGameNaming}
                className="mt-1 block w-full px-3 py-2 border rounded-lg"
                style={{
                  borderColor: 'var(--border-color)',
                  borderWidth: '1px'
                }}
                placeholder="My Awesome Game"
              />
            </label>
          </form>
          
          <div className="flex flex-wrap gap-3 justify-center">
            <button
              type="button"
              onClick={() => setGameType('wheel')}
              className="px-6 py-3 rounded-lg font-semibold transition-all duration-200"
              style={{
                backgroundColor: gameType === 'wheel' ? 'var(--primary-blue)' : '#f3f4f6',
                color: gameType === 'wheel' ? 'white' : 'var(--text-light)',
                boxShadow: gameType === 'wheel' ? 'var(--shadow-hover)' : 'none'
              }}
            >
              Wheel
            </button>
            <button
              type="button"
              onClick={() => setGameType('match')}
              className="px-6 py-3 rounded-lg font-semibold transition-all duration-200"
              style={{
                backgroundColor: gameType === 'match' ? 'var(--primary-blue)' : '#f3f4f6',
                color: gameType === 'match' ? 'white' : 'var(--text-light)',
                boxShadow: gameType === 'match' ? 'var(--shadow-hover)' : 'none'
              }}
            >
              Match
            </button>
            <button
              type="button"
              onClick={() => setGameType('quiz')}
              className="px-6 py-3 rounded-lg font-semibold transition-all duration-200"
              style={{
                backgroundColor: gameType === 'quiz' ? 'var(--primary-blue)' : '#f3f4f6',
                color: gameType === 'quiz' ? 'white' : 'var(--text-light)',
                boxShadow: gameType === 'quiz' ? 'var(--shadow-hover)' : 'none'
              }}
            >
              Quiz
            </button>
          </div>
        </div>
        
        {ConstructorEngine(gameType, gameContent, gameName)}
      </div>
    </div>
  );
}


//-----------------------------------------------------
// Wheel Game Component
//-----------------------------------------------------
const WheelGame = ({ gameName }) => {
  const textPos = { x: 0, y: 0 };
  const [items, setItems] = useState([
    { wordId: 1, wordLabel: "Math", color: "#FF6B6B", textPosition: textPos },
    { wordId: 2, wordLabel: "Science", color: "#4ECDC4", textPosition: textPos },
    { wordId: 3, wordLabel: "History", color: "#45B7D1", textPosition: textPos },
    { wordId: 4, wordLabel: "Art", color: "#96CEB4", textPosition: textPos },
    { wordId: 5, wordLabel: "Music", color: "#FFEAA7", textPosition: textPos },
    { wordId: 6, wordLabel: "Sports", color: "#DDA0DD", textPosition: textPos },
  ]);
  const [inputValue, setInputValue] = useState("");
  const [rotationDeg, setRotationDeg] = useState(0);
  const [resultLabel, setResultLabel] = useState("");
  const spinningRef = useRef(false);
  const [isSpinning, setIsSpinning] = useState(false);
  const [keepTextUpright, setKeepTextUpright] = useState(true);

  const palette = [
    "#FF6B6B",
    "#4ECDC4", 
    "#45B7D1",
    "#96CEB4",
    "#FFEAA7",
    "#DDA0DD",
    "#FFB347",
    "#95E1D3",
    "#EA8685",
    "#74B3CE"
  ];

  const handleInputChange = (event) => {
    setInputValue(event.target.value);
  };

  const handleSubmit = () => {
    const label = inputValue.trim();
    if (!label) return;
    const nextId = items.length
      ? Math.max(...items.map((i) => i.wordId)) + 1
      : 1;
    const color = palette[nextId % palette.length];
    const newItem = {
      wordId: nextId,
      wordLabel: label,
      color,
      textPosition: textPos,
    };
    setItems((prev) => [...prev, newItem]);
    setInputValue("");
  };

  const handleDelete = () => {
    const label = inputValue.trim();
    if (!label) return;
    setItems((prevItems) =>
      prevItems.filter((item) => item.wordLabel !== label)
    );
    setInputValue("");
  };

  const getPointerIndex = (deg, count) => {
    if (count <= 0) return -1;
    const adjusted = (((270 - deg) % 360) + 360) % 360;
    const step = 360 / count;
    const index = Math.floor(adjusted / step);
    return Math.min(Math.max(index, 0), count - 1);
  };

  const spin = () => {
    if (spinningRef.current || isSpinning || items.length === 0) return;
    spinningRef.current = true;
    setIsSpinning(true);
    setResultLabel("");

    const count = items.length;
    const current = rotationDeg;
    const targetIndex = Math.floor(Math.random() * count);
    const step = 360 / count;
    const targetCenterDeg = targetIndex * step + step / 2;
    const baseTargetRotation = 270 - targetCenterDeg;
    const extraTurns = 3;
    const targetRotation = baseTargetRotation + 360 * extraTurns;

    const durationMs = 5000;
    const startTs = performance.now();
    const startRotation = current;
    const deltaToBase =
      (((baseTargetRotation - startRotation) % 360) + 360) % 360;
    const endRotation = startRotation + 360 * extraTurns + deltaToBase;

    const easeOutCubic = (t) => 1 - Math.pow(1 - t, 3);

    const tick = (now) => {
      const elapsed = now - startTs;
      const t = Math.min(elapsed / durationMs, 1);
      const eased = easeOutCubic(t);
      const value = startRotation + (endRotation - startRotation) * eased;
      setRotationDeg(value);
      if (t < 1) {
        requestAnimationFrame(tick);
      } else {
        const finalIndex = getPointerIndex(value, count);
        const label = finalIndex >= 0 ? items[finalIndex]?.wordLabel ?? "" : "";
        setResultLabel(label);
        spinningRef.current = false;
        setIsSpinning(false);
      }
    };

    requestAnimationFrame(tick);
  };

  const WordWheel = ({ items, size, thickness, rotationDeg, keepTextUpright }) => {
    const computeAnglesEqual = (count) => {
      if (count <= 0) return [];
      const step = 360 / count;
      const spans = [];
      for (let i = 0; i < count; i++) {
        const startDeg = i * step;
        const endDeg = (i + 1) * step;
        spans.push({ startDeg, endDeg });
      }
      spans[spans.length - 1].endDeg = 360;
      return spans;
    };

    const donutSlicePath = (cx, cy, rOuter, rInner, startDeg, endDeg) => {
      const toRad = (d) => (d * Math.PI) / 180;
      const pt = (r, a) => ({
        x: cx + r * Math.cos(toRad(a)),
        y: cy + r * Math.sin(toRad(a)),
      });
      const largeArc = (endDeg - startDeg + 360) % 360 > 180 ? 1 : 0;
      const p1 = pt(rOuter, startDeg), p2 = pt(rOuter, endDeg);
      const p3 = pt(rInner, endDeg), p4 = pt(rInner, startDeg);
      return `M ${p1.x} ${p1.y} A ${rOuter} ${rOuter} 0 ${largeArc} 1 ${p2.x} ${p2.y} L ${p3.x} ${p3.y} A ${rInner} ${rInner} 0 ${largeArc} 0 ${p4.x} ${p4.y} Z`;
    };

    const wheelDraw = () => {
      const spans = computeAnglesEqual(items.length);
      const cx = size / 2;
      const cy = size / 2;
      const rOuter = Math.min(cx, cy) - 5;
      const rInner = Math.max(0, rOuter - thickness);
      const toRad = (d) => (d * Math.PI) / 180;
      const polarToCartesian = (r, angleDeg) => ({
        x: cx + r * Math.cos(toRad(angleDeg)),
        y: cy + r * Math.sin(toRad(angleDeg)),
      });

      return (
        <svg width={size} height={size} viewBox={`0 0 ${size} ${size}`}>
          <g transform={`rotate(${rotationDeg} ${cx} ${cy})`}>
            {spans.map((span, i) => {
              const d = donutSlicePath(
                cx,
                cy,
                rOuter,
                rInner,
                span.startDeg,
                span.endDeg
              );
              const midAngle = (span.startDeg + span.endDeg) / 2;
              const textRadius = (rOuter + rInner) / 2;
              const { x, y } = polarToCartesian(textRadius, midAngle);
              return (
                <g key={i}>
                  <path d={d} fill={items[i].color ?? "#ccc"} />
                  <text
                    x={x}
                    y={y}
                    fill="#222"
                    fontSize={Math.max(10, thickness * 0.3)}
                    textAnchor="middle"
                    dominantBaseline="middle"
                    transform={
                      keepTextUpright
                        ? `rotate(${-rotationDeg} ${x} ${y})`
                        : undefined
                    }
                  >
                    {items[i].wordLabel}
                  </text>
                </g>
              );
            })}
          </g>
          <polygon points={`${cx - 6},10 ${cx + 6},10 ${cx},28`} fill="#333" />
        </svg>
      );
    };

    return wheelDraw();
  };

  return (
    <div className="mt-8 p-6 bg-white rounded-xl shadow-lg">
      <h3 className="text-xl font-bold mb-4" style={{color: 'var(--text-dark)'}}>Wheel Game: {gameName}</h3>
      
      <div className="flex flex-col items-center">
        <WordWheel
          items={items}
          size={400}
          thickness={120}
          rotationDeg={rotationDeg}
          keepTextUpright={keepTextUpright}
        />
        
        <div className="mt-6 w-full max-w-md">
          <div className="flex mb-4">
            <input
              type="text"
              value={inputValue}
              onChange={handleInputChange}
              placeholder="Enter word"
              className="flex-1 px-4 py-2 border rounded-l-lg"
              style={{
                borderColor: 'var(--border-color)',
                borderWidth: '1px'
              }}
            />
            <button 
              onClick={handleSubmit}
              className="px-4 py-2 rounded-r-lg text-white transition-colors"
              style={{backgroundColor: 'var(--success)'}}
            >
              Add
            </button>
          </div>
          
          <div className="flex gap-2 mb-4">
            <button 
              onClick={handleDelete}
              className="px-4 py-2 rounded-lg text-white transition-colors flex-1"
              style={{backgroundColor: 'var(--error)'}}
            >
              Delete
            </button>
            <button
              onClick={spin}
              disabled={isSpinning || items.length === 0}
              className={`px-4 py-2 rounded-lg flex-1 transition-colors ${
                isSpinning || items.length === 0
                  ? 'opacity-60 cursor-not-allowed'
                  : 'text-white'
              }`}
              style={{
                backgroundColor: isSpinning || items.length === 0 ? '#9ca3af' : 'var(--primary-blue)'
              }}
            >
              {isSpinning ? 'Spinning...' : 'Spin Wheel'}
            </button>
          </div>
          
          <label className="flex items-center">
            <input
              type="checkbox"
              checked={keepTextUpright}
              onChange={(e) => setKeepTextUpright(e.target.checked)}
              className="mr-2"
            />
            Keep text upright
          </label>
        </div>
        
        {resultLabel && (
          <div className="mt-6 border px-4 py-3 rounded-lg" style={{
            backgroundColor: '#dff0d8',
            borderColor: '#d6e9c6',
            color: '#3c763d'
          }}>
            <span className="font-bold">Winner:</span> {resultLabel}
          </div>
        )}
      </div>
    </div>
  );
}

export default GameConstructor;
